            <!-- 16 grid cells -->
            <div class="grid-cell"></div><div class="grid-cell"></div><div class="grid-cell"></div><div class="grid-cell"></div>
            <div class="grid-cell"></div><div class="grid-cell"></div><div class="grid-cell"></div><div class="grid-cell"></div>
            <div class="grid-cell"></div><div class="grid-cell"></div><div class="grid-cell"></div><div class="grid-cell"></div>
            <div class="grid-cell"></div><div class="grid-cell"></div><div class="grid-cell"></div><div class="grid-cell"></div>
        </div>
        <div class="tile-container" id="tile-container">
            <!-- Tiles will be added here by JavaScript -->
        </div>
    </div>

    <div class="ad-banner">
        <img src="__PLACEHOLDER_ASSETS_BASE_DIR__/015.png" alt="Advertisement banner" width="300" height="200">
    </div>

    <div class="instructions">
        <p>Use your arrow keys (also W, A, S, and D keys alternatively) or swipe with your fingers to move the tiles. For example, if you joined 2 tiles with the number 2, they will become 4, 2 tiles with 4 will become 8, and so on. The point of the game is to get the 2048 tile!</p>
    </div>

    <div class="other-games">
        <h2>Play Other Games</h2>
        <div class="games-grid">
            <div class="game-card btn">
                <img src="__PLACEHOLDER_ASSETS_BASE_DIR__/004.png" alt="Tetris-like game" width="150" height="100">
            </div>
            <div class="game-card btn">
                <img src="__PLACEHOLDER_ASSETS_BASE_DIR__/007.png" alt="Number puzzle game" width="150" height="100">
            </div>
            <div class="game-card btn">
                <img src="__PLACEHOLDER_ASSETS_BASE_DIR__/008.png" alt="Math game" width="150" height="100">
            </div>
