    <script>
        // Game State
        const gridSize = 4;
        let board = [];
        let score = 0;
        let bestScore = localStorage.getItem('2048-best') || 0;
        let gameOver = false;

        // DOM Elements
        const tileContainer = document.getElementById('tile-container');
        const currentScoreEl = document.getElementById('current-score');
        const bestScoreEl = document.getElementById('best-score');
        const newGameBtn = document.getElementById('new-game-btn');
        const classicThemeBtn = document.getElementById('classic-theme');
        const cupcakesThemeBtn = document.getElementById('cupcakes-theme');
        const gameContainer = document.getElementById('game-container');

        // Initialize Game
        function initGame() {
            board = Array(gridSize).fill(null).map(() => Array(gridSize).fill(0));
            score = 0;
            gameOver = false;
            updateScoreDisplay();
            renderBoard();

            // Add two initial tiles
            addRandomTile();
            addRandomTile();
        }

        // Add a random tile (2 or 4) to an empty cell
        function addRandomTile() {
            const emptyCells = [];
            for (let r = 0; r < gridSize; r++) {
                for (let c = 0; c < gridSize; c++) {
                    if (board[r][c] === 0) {
                        emptyCells.push({r, c});
                    }
                }
            }

            if (emptyCells.length > 0) {
                const randomCell = emptyCells[Math.floor(Math.random() * emptyCells.length)];
                board[randomCell.r][randomCell.c] = Math.random() < 0.9 ? 2 : 4;
                renderBoard();
            }
        }

        // Render the board
        function renderBoard() {
            tileContainer.innerHTML = '';

            for (let r = 0; r < gridSize; r++) {
                for (let c = 0; c < gridSize; c++) {
                    if (board[r][c] !== 0) {
                        const tile = document.createElement('div');
                        tile.className = 'tile';
                        tile.textContent = board[r][c];
                        tile.setAttribute('data-val', board[r][c]);

                        // Calculate position
                        const gap = 15; // Gap between cells in px
                        const containerWidth = gameContainer.offsetWidth - 30; // Total width minus padding
                        const cellSize = (containerWidth - (3 * gap)) / 4;

                        tile.style.width = `${cellSize}px`;
                        tile.style.height = `${cellSize}px`;
                        tile.style.transform = `translate(${c * (cellSize + gap)}px, ${r * (cellSize + gap)}px)`;

                        tileContainer.appendChild(tile);
                    }
                }
            }
        }

        // Update score display
        function updateScoreDisplay() {
            currentScoreEl.textContent = score;
            if (score > bestScore) {
                bestScore = score;
                localStorage.setItem('2048-best', bestScore);
            }
            bestScoreEl.textContent = bestScore;
        }

        // Show score popup
        function showScorePopup(points) {
            const popup = document.createElement('div');
            popup.className = 'score-popup';
            popup.textContent = `+${points}`;
            gameContainer.appendChild(popup);

            setTimeout(() => {
                popup.remove();
            }, 800);
        }

        // Move tiles in a specific direction
        function move(direction) {
            if (gameOver) return;

            let moved = false;
            let pointsGained = 0;

            // Create a copy of the board
            const newBoard = board.map(row => [...row]);

            if (direction === 'left' || direction === 'right') {
                for (let r = 0; r < gridSize; r++) {
                    const row = newBoard[r].filter(val => val !== 0);

                    if (direction === 'left') {
                        for (let i = 0; i < row.length - 1; i++) {
                            if (row[i] === row[i + 1]) {
                                row[i] *= 2;
                                pointsGained += row[i];
                                row.splice(i + 1, 1);
                            }
                        }
                    } else {
                        for (let i = row.length - 1; i > 0; i--) {
                            if (row[i] === row[i - 1]) {
                                row[i] *= 2;
                                pointsGained += row[i];
                                row.splice(i - 1, 1);
                            }
                        }
                    }

                    // Pad with zeros
                    while (row.length < gridSize) {
                        if (direction === 'left') row.push(0);
                        else row.unshift(0);
                    }

                    newBoard[r] = row;
                }
            } else {
                for (let c = 0; c < gridSize; c++) {
                    const col = [];
                    for (let r = 0; r < gridSize; r++) {
                        if (newBoard[r][c] !== 0) col.push(newBoard[r][c]);
                    }

                    if (direction === 'up') {
                        for (let i = 0; i < col.length - 1; i++) {
                            if (col[i] === col[i + 1]) {
                                col[i] *= 2;
                                pointsGained += col[i];
                                col.splice(i + 1, 1);
                            }
                        }
                    } else {
                        for (let i = col.length - 1; i > 0; i--) {
                            if (col[i] === col[i - 1]) {
                                col[i] *= 2;
                                pointsGained += col[i];
                                col.splice(i - 1, 1);
                            }
                        }
                    }

                    // Pad with zeros
                    while (col.length < gridSize) {
                        if (direction === 'up') col.push(0);
                        else col.unshift(0);
                    }

                    for (let r = 0; r < gridSize; r++) {
                        newBoard[r][c] = col[r];
                    }
                }
            }

            // Check if board changed
            for (let r = 0; r < gridSize; r++) {
                for (let c = 0; c < gridSize; c++) {
                    if (board[r][c] !== newBoard[r][c]) {
                        moved = true;
                        break;
                    }
                }
            }

            if (moved) {
                board = newBoard;
                score += pointsGained;
                updateScoreDisplay();

                if (pointsGained > 0) {
                    showScorePopup(pointsGained);
                }

                renderBoard();
                addRandomTile();
                checkGameOver();
            }
        }

        // Check if game is over
        function checkGameOver() {
            // Check for empty cells
            for (let r = 0; r < gridSize; r++) {
                for (let c = 0; c < gridSize; c++) {
                    if (board[r][c] === 0) return;
                }
            }

            // Check for possible merges
            for (let r = 0; r < gridSize; r++) {
                for (let c = 0; c < gridSize; c++) {
                    if (c < gridSize - 1 && board[r][c] === board[r][c + 1]) return;
                    if (r < gridSize - 1 && board[r][c] === board[r + 1][c]) return;
                }
            }

            gameOver = true;
            setTimeout(() => alert('Game Over!'), 100);
        }

        // Event Listeners
        document.addEventListener('keydown', (e) => {
            switch(e.key) {
                case 'ArrowUp':
                case 'w':
                case 'W':
                    e.preventDefault();
                    move('up');
                    break;
                case 'ArrowDown':
                case 's':
                case 'S':
                    e.preventDefault();
                    move('down');
                    break;
                case 'ArrowLeft':
                case 'a':
                case 'A':
                    e.preventDefault();
                    move('left');
                    break;
                case 'ArrowRight':
                case 'd':
                case 'D':
                    e.preventDefault();
                    move('right');
                    break;
            }
        });

        newGameBtn.addEventListener('click', initGame);

        // Touch/Swipe support
        let touchStartX = 0;
        let touchStartY = 0;

        gameContainer.addEventListener('touchstart', (e) => {
            touchStartX = e.touches[0].clientX;
            touchStartY = e.touches[0].clientY;
        }, {passive: false});

        gameContainer.addEventListener('touchend', (e) => {
            if (!touchStartX || !touchStartY) return;

            const touchEndX = e.changedTouches[0].clientX;
            const touchEndY = e.changedTouches[0].clientY;

            const diffX = touchEndX - touchStartX;
            const diffY = touchEndY - touchStartY;

            if (Math.abs(diffX) > Math.abs(diffY)) {
                if (Math.abs(diffX) > 30) {
                    if (diffX > 0) move('right');
                    else move('left');
                }
            } else {
                if (Math.abs(diffY) > 30) {
                    if (diffY > 0) move('down');
                    else move('up');
                }
            }

            touchStartX = 0;
            touchStartY = 0;
        }, {passive: false});

        // Theme switching (mock functionality)
        classicThemeBtn.addEventListener('click', () => {
            classicThemeBtn.classList.add('active');
            cupcakesThemeBtn.classList.remove('active');
            // In a real implementation, this would change CSS variables
        });

        cupcakesThemeBtn.addEventListener('click', () => {
            cupcakesThemeBtn.classList.add('active');
            classicThemeBtn.classList.remove('active');
            // In a real implementation, this would change CSS variables
        });

        // Other games cards click handlers
        document.querySelectorAll('.game-card').forEach(card => {
            card.addEventListener('click', () => {
                alert('This feature would redirect to another game.');
            });
        });

        // Initialize the game on load
        window.addEventListener('load', () => {
            bestScoreEl.textContent = bestScore;
            initGame();
        });

        // Handle window resize
        window.addEventListener('resize', () => {
            renderBoard();
        });
    </script>
</body>
</html>
